 if(($_POST['category']??'')==='heating'&&!empty($_POST['apportionable'])){if(empty($_POST['co2_approved']))throw new RuntimeException('Heiz-/CO2-Entscheidung ausdrücklich bestätigen.');$decision=(string)($_POST['co2_decision']??'');$owner=estateAmount($_POST,'co2_owner',true);$in['co2']=['decision'=>$decision,'source_id'=>opsText($_POST,'co2_source',190,true),'reason'=>opsText($_POST,'co2_reason',1000,true),'approved'=>true,'owner_cents'=>$owner];}
 estateCostSave($pdo,$admin,$in,(int)($_POST['cost_id']??0));}
