try{estateSettlementRequire($pdo);$buildings=$pdo->query('SELECT * FROM estate_buildings ORDER BY name,id LIMIT 500')->fetchAll();$settings=$pdo->query('SELECT * FROM estate_settings WHERE id=1')->fetch();if(!$building&&$buildings){$building=(int)$buildings[0]['id'];redirect('estate_settlements.php?building='.$building.'&from='.$from.'&to='.$to.'&as_of='.$asOf);}if($building){$q=$pdo->prepare('SELECT * FROM estate_documents WHERE building_id=? OR building_id IS NULL ORDER BY id DESC LIMIT 500');$q->execute([$building]);$documents=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM estate_costs WHERE building_id=? AND period_from<=? AND period_to>=? ORDER BY id DESC LIMIT 501');$q->execute([$building,$to,$from]);$costs=$q->fetchAll();if(count($costs)>500)throw new RuntimeException('Kostenliste auf engeren Zeitraum begrenzen.');if($costEdit){$q=$pdo->prepare('SELECT * FROM estate_costs WHERE id=? AND building_id=?');$q->execute([$costEdit,$building]);$row=$q->fetch()?:[];}$q=$pdo->prepare('SELECT id,period_from,period_to,as_of,version,supersedes_id,created_at FROM estate_settlements WHERE building_id=? ORDER BY created_at DESC,id DESC LIMIT 100');$q->execute([$building]);$settlements=$q->fetchAll();try{$recipients=estateDistributionRecipients($pdo,$building,$from,$to);}catch(Throwable $e){$recipientError=$e->getMessage();}}
 if(isset($_GET['proposal'])){$q=$pdo->prepare('SELECT * FROM estate_settlement_proposals WHERE token=? AND admin_id=? AND building_id=?');$q->execute([(string)$_GET['proposal'],$admin,$building]);$proposal=$q->fetch();if($proposal)$payload=json_decode($proposal['payload'],true,128,JSON_THROW_ON_ERROR);}
 if($selected){$final=estateSettlementRead($pdo,$selected);if((int)$final['building_id']!==$building)throw new RuntimeException('Abrechnung gehört zu anderem Gebäude.');$payload=$final['snapshot'];$q=$pdo->prepare('SELECT * FROM estate_settlement_documents WHERE settlement_id=? ORDER BY lease_id');$q->execute([$selected]);$pdfs=$q->fetchAll();}
 if($payload){$period=$payload['calculation']['period'];$q=$pdo->prepare('SELECT id FROM estate_settlements WHERE building_id=? AND period_to<? ORDER BY period_to DESC,version DESC LIMIT 1');$q->execute([$building,$period['from']]);if($prev=$q->fetchColumn())$prior=estateSettlementRead($pdo,(int)$prev);}$ready=true;
 $bankCosts=[];if($building){$q=$pdo->prepare('SELECT e.category,SUM(-t.amount_cents) cents,COUNT(*) n,MIN(e.document_id) document_id FROM estate_expenses e JOIN estate_bank_transactions t ON t.id=e.transaction_id WHERE e.building_id=? AND t.booked_on BETWEEN ? AND ? GROUP BY e.category ORDER BY e.category');$q->execute([$building,$from,$to]);$bankCosts=$q->fetchAll();}
 $pre=(string)($_GET['pre']??'');if(!$costEdit&&$pre!=='')foreach($bankCosts as $bc)if($bc['category']===$pre){$kind=match(true){$pre==='Heizung / Gas'=>'heating',$pre==='Reparatur / Instandhaltung'=>'maintenance',$pre==='Verwaltung'=>'administration',in_array($pre,['Kredit / Zinsen','Bankgebühren','Sonstige Kosten'],true)=>'other_non_apportionable',default=>'operating'};$row=['title'=>$pre,'amount_cents'=>(int)$bc['cents'],'category'=>$kind,'document_id'=>(int)$bc['document_id'],'period_from'=>$from,'period_to'=>$to];}
}catch(Throwable $e){gszUiError($e);}estatePage('Nebenkostenabrechnung');
