<?php if($payload):$calc=$payload['calculation'];?><section class="card" id="s-pdf"><h2><?=$final?'Archivierte Abrechnung Version '.(int)$final['version']:'Vorschau – noch nicht abgeschlossen'?></h2><p><?=e($calc['period']['from'].'–'.$calc['period']['to'])?> · Zahlungsstand <?=e($calc['as_of'])?></p><?php $manual=count(array_filter($payload['state']['payment_rows'],fn($a)=>$a['bank_transaction_id']===null));if($manual):?><p class="error">Manuell erfasste Vorauszahlungszeilen ohne verknüpften Bankumsatz: <?=$manual?>. Tatsächliche Nachweise vor Freigabe prüfen; keine bestätigte Bankverbindung behauptet.</p><?php endif?><p>Gesamtkosten <?=e(estateMoney($calc['totals']['cost_cents']))?> EUR = Mieteranteil <?=e(estateMoney($calc['totals']['tenant_cost_cents']))?> + Eigentümeranteil <?=e(estateMoney($calc['totals']['owner_cents']))?> EUR. Nicht umlagefähige Kosten <?=e(estateMoney($calc['totals']['excluded_cents']))?> EUR sind im Eigentümeranteil bereits enthalten.</p><?php $leaseNames=array_column($payload['state']['leases'],'tenant_name','id');foreach($calc['tenant_statements'] as $s):?><article class="task-row"><strong><?=e($leaseNames[$s['occupancy_id']]??('Vertrag #'.$s['occupancy_id']))?></strong><p>Kosten <?=e(estateMoney($s['cost_cents']))?> · Ist-Vorauszahlungen <?=e(estateMoney($s['advance_cents']))?> · <?=$s['balance_cents']>=0?'Nachzahlung':'Guthaben'?> <?=e(estateMoney(abs($s['balance_cents'])))?> EUR</p></article><?php endforeach?><?php if($prior):$pcalc=$prior['snapshot']['calculation'];?><p>Vorige gespeicherte Periode <?=e($prior['period_from'].'–'.$prior['period_to'])?>: Gesamtkosten <?=e(estateMoney($pcalc['totals']['cost_cents']))?> EUR. Zeiträume/Einheiten können abweichen; keine bereinigte Prozentvergleichsbehauptung.</p><?php endif?><?php if(!$final&&$proposal):?><form method="post"><?php gszFields('apply');?><input type="hidden" name="token" value="<?=e($proposal['token'])?>"><label><input type="checkbox" name="reviewed" required> Verträge, Einheiten/Flächen, Belege/Zeiträume, Umlagen, tatsächliche Vorauszahlungen und ggf. externe Heiz-/CO₂-Grundlagen geprüft. Version/PDF endgültig archivieren, nicht versenden.</label><label><input type="checkbox" name="revision"> Falls bereits eine Abrechnung existiert: ausdrücklich neue Korrekturversion, alte Version/Originale behalten.</label><button>Abrechnung als Version abschließen</button></form><?php endif?><?php if($final):?><p><a href="estate_settlement_export.php?id=<?=(int)$final['id']?>">Privates Eigentümer-/Beraterpaket mit Originalen und Prüfsummen</a> – enthält alle Mieterdaten; nicht als Mieterpaket weitergeben.</p><?php endif?><?php foreach($pdfs as $pdf):?><p>Vertrag #<?=(int)$pdf['lease_id']?> · <a href="estate_statement.php?id=<?=(int)$pdf['id']?>">Archiviertes Mieter-PDF</a></p><?php endforeach?><details><summary>Vollständige nachvollziehbare Berechnung</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?=e(json_encode($calc,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details></section><?php endif?>
<section class="card"><h2>Abrechnungshistorie</h2><?php foreach($settlements as $s):?><p><a href="estate_settlements.php?building=<?=$building?>&amp;from=<?=e($s['period_from'])?>&amp;to=<?=e($s['period_to'])?>&amp;as_of=<?=e($s['as_of'])?>&amp;settlement=<?=(int)$s['id']?>"><?=e($s['period_from'].'–'.$s['period_to'])?> · Version<?=(int)$s['version']?></a> · <?=e($s['created_at'])?> UTC <?=$s['supersedes_id']?'· Korrektur zu #'.(int)$s['supersedes_id']:''?></p><?php endforeach?></section><?php endif?><?php gszPageEnd();?>
